-- Independent read-only schema and bounded initialization verification.
BEGIN READ ONLY;
SET LOCAL search_path=pg_catalog;
SET LOCAL statement_timeout='20s';
SET LOCAL lock_timeout='2s';
SET LOCAL idle_in_transaction_session_timeout='15s';
DO $account_guard$
DECLARE observed jsonb;
BEGIN
  WITH actor_functions AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'signature',p.oid::regprocedure::text,
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'owner',pg_get_userbyid(p.proowner)) ORDER BY p.oid::regprocedure::text),'[]'::jsonb) value
 FROM pg_proc p WHERE p.oid IN (SELECT to_regprocedure(x) FROM unnest(ARRAY['auth.uid()','listing_publication_private.require_actor(uuid,uuid)','profile_editor_private.touch_revision()','public.current_user_has_identity_access(uuid)','public.get_my_identities()','public.is_business_member(uuid)','public.listing_actor_uid_hosted_v1()','public.lock_listing_creation_actor_v1(uuid)','public.set_my_active_identity_v2(uuid)','public.user_has_identity_access_v2(uuid,uuid)','public.validate_profile_active_identity_v2()']) x)
), protected_triggers AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'relation',t.tgrelid::regclass::text,'name',t.tgname,'function',t.tgfoid::regprocedure::text,
  'enabled',t.tgenabled::text,'event_mask',t.tgtype,'argument_count',t.tgnargs,
  'arguments_sha256',encode(sha256(t.tgargs),'hex'),
  'when_sha256',CASE WHEN t.tgqual IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(t.tgqual,t.tgrelid),'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_triggerdef(t.oid),'UTF8')),'hex')) ORDER BY t.tgrelid::regclass::text,t.tgname),'[]'::jsonb) value
 FROM (SELECT * FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN
  (SELECT to_regclass(x) FROM unnest(ARRAY['auth.users','public.profiles','public.identities','public.identity_profiles','public.business_accounts','public.business_members']) x)
  AND NOT (tgrelid=to_regclass('auth.users') AND tgname='initialize_account_state') ORDER BY tgrelid,tgname LIMIT 8) t
), base AS (
 SELECT jsonb_build_object(
  'actor_functions',(SELECT value FROM actor_functions),
  'auth_columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,
   'default_sha256',CASE WHEN d.oid IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(d.adbin,d.adrelid),'UTF8')),'hex') END) ORDER BY a.attname)
   FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=to_regclass('auth.users') AND NOT a.attisdropped AND a.attname IN ('id','created_at','banned_until','deleted_at')),'[]'::jsonb),
  'auth_owner',(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=to_regclass('auth.users')),
  'auth_kind',(SELECT relkind::text FROM pg_class WHERE oid=to_regclass('auth.users')),
  'auth_rls',(SELECT relrowsecurity FROM pg_class WHERE oid=to_regclass('auth.users')),
  'auth_primary_key',COALESCE((SELECT jsonb_agg(a.attname ORDER BY k.ord) FROM pg_constraint con CROSS JOIN LATERAL unnest(con.conkey) WITH ORDINALITY k(num,ord)
   JOIN pg_attribute a ON a.attrelid=con.conrelid AND a.attnum=k.num WHERE con.conrelid=to_regclass('auth.users') AND con.contype='p' AND con.convalidated AND NOT con.condeferrable),'[]'::jsonb),
  'protected_triggers',(SELECT value FROM protected_triggers),
  'roles',(SELECT jsonb_agg(rolname ORDER BY rolname) FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')),
  'observer',current_user,
  'auth_privileges',COALESCE(has_table_privilege(current_user,to_regclass('auth.users'),'SELECT') AND has_table_privilege(current_user,to_regclass('auth.users'),'TRIGGER') AND has_table_privilege(current_user,to_regclass('auth.users'),'REFERENCES'),false)
 ) value
), target_functions AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'name',n.nspname||'.'||p.proname,
  'arguments',COALESCE((SELECT jsonb_agg(format_type(a,NULL) ORDER BY ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY x(a,ord)),'[]'::jsonb),
  'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
  'definer',p.prosecdef,'volatility',p.provolatile::text,'strict',p.proisstrict,'parallel',p.proparallel::text,'leakproof',p.proleakproof,
  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'defaults',p.pronargdefaults<>0,
  'grants',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type)
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) value
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='account_lifecycle_private' OR (n.nspname='public' AND p.proname='get_my_account_state_v1') ORDER BY n.nspname,p.proname,p.oid LIMIT 4) p
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
), target AS (
 SELECT jsonb_build_object(
  'schema_owner',(SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='account_lifecycle_private'),
  'schema_owner_only',NOT EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='account_lifecycle_private' AND a.grantee<>n.nspowner),
  'schema_app_denied',NOT EXISTS(SELECT 1 FROM pg_roles r JOIN pg_namespace n ON n.nspname='account_lifecycle_private' WHERE r.rolname IN ('anon','authenticated','service_role') AND (has_schema_privilege(r.oid,n.oid,'USAGE') OR has_schema_privilege(r.oid,n.oid,'CREATE'))),
  'relation_count',(SELECT count(*) FROM (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='account_lifecycle_private' AND c.relkind IN ('r','p','v','m','S','f') LIMIT 3) bounded),
  'table_owner',(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'table_kind',(SELECT relkind::text FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'rls',(SELECT relrowsecurity FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'force_rls',(SELECT relforcerowsecurity FROM pg_class WHERE oid=to_regclass('account_lifecycle_private.account_states')),
  'owner_grants_only',NOT EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=to_regclass('account_lifecycle_private.account_states') AND a.grantee<>c.relowner),
  'column_grants_owner_only',NOT EXISTS(SELECT 1 FROM pg_attribute col JOIN pg_class c ON c.oid=col.attrelid CROSS JOIN LATERAL aclexplode(col.attacl) a WHERE c.oid=to_regclass('account_lifecycle_private.account_states') AND a.grantee<>c.relowner),
  'table_app_denied',NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role') AND
   (has_table_privilege(r.oid,to_regclass('account_lifecycle_private.account_states'),'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege(r.oid,to_regclass('account_lifecycle_private.account_states'),'SELECT,INSERT,UPDATE,REFERENCES'))),
  'columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text,
   'default_sha256',CASE WHEN d.oid IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(d.adbin,d.adrelid),'UTF8')),'hex') END) ORDER BY a.attnum)
   FROM (SELECT * FROM pg_attribute WHERE attrelid=to_regclass('account_lifecycle_private.account_states') AND attnum>0 AND NOT attisdropped ORDER BY attnum LIMIT 8) a
   LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum),'[]'::jsonb),
  'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',con.conname,'kind',con.contype::text,'definition_sha256',encode(sha256(convert_to(pg_get_constraintdef(con.oid),'UTF8')),'hex'),'validated',con.convalidated,'deferrable',con.condeferrable) ORDER BY con.conname)
   FROM (SELECT * FROM pg_constraint WHERE conrelid=to_regclass('account_lifecycle_private.account_states') ORDER BY conname LIMIT 8) con),'[]'::jsonb),
  'table_triggers',(SELECT count(*) FROM (SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass('account_lifecycle_private.account_states') AND NOT tgisinternal LIMIT 2) bounded),
  'policies',(SELECT count(*) FROM (SELECT 1 FROM pg_policy WHERE polrelid=to_regclass('account_lifecycle_private.account_states') LIMIT 2) bounded),
  'indexes',(SELECT count(*) FROM (SELECT 1 FROM pg_index WHERE indrelid=to_regclass('account_lifecycle_private.account_states') LIMIT 3) bounded),
  'functions',(SELECT value FROM target_functions),
  'auth_triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('definition_sha256',encode(sha256(convert_to(pg_get_triggerdef(t.oid),'UTF8')),'hex'),'name',t.tgname,'function',t.tgfoid::regprocedure::text,'enabled',t.tgenabled::text,'event_mask',t.tgtype,'argument_count',t.tgnargs,
   'arguments_sha256',encode(sha256(t.tgargs),'hex'),'when_sha256',CASE WHEN t.tgqual IS NULL THEN NULL ELSE encode(sha256(convert_to(pg_get_expr(t.tgqual,t.tgrelid),'UTF8')),'hex') END) ORDER BY t.tgname)
   FROM (SELECT * FROM pg_trigger WHERE tgrelid=to_regclass('auth.users') AND NOT tgisinternal ORDER BY tgname LIMIT 4) t),'[]'::jsonb)
 ) value
), evaluated AS (
 SELECT base.value b,target.value t,
 CASE WHEN base.value='{"actor_functions":[{"signature":"auth.uid()","body_sha256":"9ab5ea099e74ec09e83b1505c51a3647791195aed7c742dcc3f257dfc7d2f300","definition_sha256":"7c1ff2ecbe653c9358b3115a2607db9573f88a2944ae4eca9e296a89cc5186a7","config_sha256":null,"owner":"supabase_auth_admin"},{"signature":"listing_publication_private.require_actor(uuid,uuid)","body_sha256":"9a86e4ca817793a77420dfc2e74d9e2df18298436638a7bf241428fca2c9a3f0","definition_sha256":"6ef892a8a4bd1f80224bd61e40b61eaf3e4c014853a72703088922de8dd91a69","config_sha256":"a983dc37b42030987a873720dfdd7abc6aedb3d4b2f64c7cd5dd68adfc8158d0","owner":"postgres"},{"signature":"profile_editor_private.touch_revision()","body_sha256":"7db83fbd1e0cae0d5f997df4470903a7ddefce15177ca2bb8731cc0920fae03a","definition_sha256":"1fe60ef3851ed8ca9d9859436f4ce8d0aaef7647385c47fadfe513dc5887c1a3","config_sha256":"0e5c5deb67bdf8a0f1c087edd287aeab8d3ca04e5548a7679dd526aad7d8d491","owner":"postgres"},{"signature":"public.current_user_has_identity_access(uuid)","body_sha256":"b708d7abdfac00c7341979f4ff6dfae2ab2bfb55d311f27c7cc2935167224027","definition_sha256":"7abc16984c11888b82a816d1de9a2fa83edd7e2516c4a906c98a61433777d68d","config_sha256":"dea4cee856bd28f242d5772a4e469a64836a0e8cbde23a167c7eb9f39f70835b","owner":"postgres"},{"signature":"public.get_my_identities()","body_sha256":"958857777e1ef23101200b8425402560f543415cd52be22c2365aa5fceedd058","definition_sha256":"4dce8ba8ee855a770770a939379f6acecb2ee58b34fa348bcba71d5c46a85505","config_sha256":"a90d5406c7d8f6b00e8de7e96010c8d845fbd78bf3325ddb6931ef9c21a2dd90","owner":"postgres"},{"signature":"public.is_business_member(uuid)","body_sha256":"86edbe18df1d369effc9f2dc62e6990066f6ddd548eae86889ef8a7be9f2905f","definition_sha256":"19ee8712081060eb5d9b49e24bb902b6f1bc5d3f9817ea382b450d172834f007","config_sha256":"a90d5406c7d8f6b00e8de7e96010c8d845fbd78bf3325ddb6931ef9c21a2dd90","owner":"postgres"},{"signature":"public.listing_actor_uid_hosted_v1()","body_sha256":"ff7f6ce615280095